// SearchVehiclesWithBodyWithResponse Найти похожие автомобили или вернуть отказ
//
// Запрос не добавляется в галерею. Сходство — cosine similarity в [-1, 1],
// больше означает ближе; это не калиброванная вероятность. Для pgvector
// score = 1 - cosine_distance. Результаты сортируются по confidence DESC,
// при равенстве — observation.id ASC. Возвращается не более top_k объектов.
// candidates: включаются только confidence >= threshold (по умолчанию 0.36).
// Пустой список означает refused=true; причина empty_gallery, если после
// исключений галерея пуста, иначе below_threshold.
// ranking: порог не применяется; возвращаются ближайшие объекты, даже
// при низкой уверенности; refused всегда false, refusal_reason=null,
// threshold=null. Это режим подготовки top-10 для submission.csv.
// Результаты относятся к наблюдениям и не объединяются по vehicle_id.
// Поиск использует ANN/HNSW, поэтому полнота ближайших соседей приближённая.
// Нулевой/нечисловой результат модели — ошибка 503, а не отказ.
//
// Takes any type of body and a specified content type, and returns a wrapper object for the known response body format(s).
//
// Corresponds with POST /api/v1/search (the `SearchVehicles` operationId).
func (c *ClientWithResponses) SearchVehiclesWithBodyWithResponse(ctx context.Context, contentType string, body io.Reader, reqEditors ...RequestEditorFn) (*SearchVehiclesResponse, error) {
	rsp, err := c.SearchVehiclesWithBody(ctx, contentType, body, reqEditors...)
	if err != nil {
		return nil, err
	}
	return ParseSearchVehiclesResponse(rsp)
}

